		[Test]
		public void TestXMLMessageSuccess_SYS()
		{
			var adapter = CreateAdapter(TestClientID, LicencedSenderPassword);
			using (var messageStream = new MemoryStream(Encoding.UTF8.GetBytes(SysMessage)))
			{
				var messagePK = Guid.NewGuid();
				var message = new eHubMessage(messagePK, TestClientID, eHubSystemID, MessageSchemaType.Xml, ApplicationCode.SYS, "", messageStream);
				adapter.Outbox.AddMessage(message);
				adapter.SendMessages();

				var content = StreamExtensions.CompressAndEncode(messageStream).ReadToEnd();
				AssertInboxMessage(messagePK, TestClientPK, ApplicationCode.SYS, eHubSystemPK, "http://www.cargowise.com/Schemas/System#SystemInterchange", "", "", content, 0, 2);
				var x = new MemoryStream(Encoding.UTF8.GetBytes(messageStream.ReadToEnd().Replace("<?xml version=\"1.0\" encoding=\"utf-8\"?>", "").Trim()));
                var outboxContent = x.CompressAndEncode();
                Assert.IsTrue(FindOutboxMessage(messagePK, TestClientPK, eHubSystemPK, SYSMessageTypePK, "", "", 0, x.ReadToEnd(), outboxContent.ReadToEnd()));
				AssertInboxXmlContent(messagePK, SYSMessageTypePK, x.ReadToEnd());

			}
		}

		[Test]
		public void TestFlatFileMessageSuccess_ZAC()
		{
			var adapter = CreateAdapter(LicencedSenderID, TestAuthenticatedClientPassword);
			using (var messageStream = new MemoryStream(Encoding.UTF8.GetBytes(ZACustomsMessage)))
			{
				var messagePK = Guid.NewGuid();
				var message = new eHubMessage(messagePK, LicencedSenderID, ZACustomsID, MessageSchemaType.FlatFile, ApplicationCode.ZACustoms, "", messageStream);
				adapter.Outbox.AddMessage(message);
				adapter.SendMessages();

				var content = StreamExtensions.CompressAndEncode(messageStream).ReadToEnd();
				AssertInboxMessage(messagePK, LicencedSenderPK, ApplicationCode.ZACustoms, ZACustomsPK, "", "", "", content, 1, 2);
                Assert.IsTrue(FindOutboxMessage(messagePK, LicencedSenderPK, ZACustomsPK, null, "", "", 0, null, content));

			}
		}

