		[Test]
        public void TestXMLMessageSuccess_TEL_WithBOM()
        {
            var adapter = CreateAdapter(LicencedSenderID, TestAuthenticatedClientPassword);
            var bytes = Encoding.UTF8.GetBytes(TelMessage);
            var preAdded = Encoding.UTF8.GetPreamble().Concat(bytes).ToArray();
            using (var messageStream = new MemoryStream(preAdded))
            {
                var messagePK = Guid.NewGuid();
                var message = new eHubMessage(messagePK, LicencedSenderID, TestClientID, MessageSchemaType.Xml, ApplicationCode.Telematics, "", messageStream);
                adapter.Outbox.AddMessage(message);
                adapter.SendMessages();

                var content = StreamExtensions.CompressAndEncode(messageStream).ReadToEnd();
                AssertInboxMessage(messagePK, LicencedSenderPK, ApplicationCode.Telematics, TestClientPK, "http://cargowise.com/ehub/products/telematics/2013/05#TelematicsInterchange", "", "", content, 0, 2);
                var x = new MemoryStream(Encoding.UTF8.GetBytes(messageStream.ReadToEnd().Replace("<?xml version=\"1.0\" encoding=\"utf-8\"?>", "").Trim()));
                var outboxContent = x.CompressAndEncode();
                Assert.IsTrue(FindOutboxMessage(messagePK, LicencedSenderPK, TestClientPK, TELMessageTypePK, "", "", 0, x.ReadToEnd(), outboxContent.ReadToEnd()));
                AssertInboxXmlContent(messagePK, TELMessageTypePK, x.ReadToEnd());

            }
        }

