        [Test]
        public void TestXMLMessageSuccess_GMD()
        {
            const string MSG_TYPE = "http://cargowise.com/ehub/core/genericmessagedelivery#GenericMessageInterface";

            var adapter = CreateAdapter(LicencedSenderID, TestAuthenticatedClientPassword);
            using (var messageStream = new MemoryStream(Encoding.UTF8.GetBytes(GenericMessage)))
            {
                var messagePK = Guid.NewGuid();
                var message = new eHubMessage(messagePK, LicencedSenderID, GMDID, MessageSchemaType.Xml, ApplicationCode.GenericMessageDelivery, MSG_TYPE, messageStream);

                adapter.Outbox.AddMessage(message);
                adapter.SendMessages();

                var content = StreamExtensions.CompressAndEncode(messageStream).ReadToEnd();
                AssertInboxMessage(messagePK, LicencedSenderPK, ApplicationCode.GenericMessageDelivery, GMDPK, MSG_TYPE, "", "", content, 0, 2);
                var x = new MemoryStream(Encoding.UTF8.GetBytes(messageStream.ReadToEnd().Trim()));
                var outboxContent = x.CompressAndEncode();
                Assert.IsTrue(FindOutboxMessage(messagePK, LicencedSenderPK, GMDPK, GMDMessageTypePK, "", "", 0, x.ReadToEnd(), outboxContent.ReadToEnd()), "Outbox message not found");
                AssertInboxXmlContent(messagePK, GMDMessageTypePK, x.ReadToEnd());

            }
        }

