	    [Test]
		public void TestXMLMessageSuccess_NDM()
		{
			// Arrange
			var adapter = CreateAdapter(LicencedSenderID, TestAuthenticatedClientPassword);
			using (var messageStream = new MemoryStream(Encoding.UTF8.GetBytes(NDMMessage)))
			{
				var messagePK = Guid.NewGuid();
				var message = new eHubMessage(messagePK, LicencedSenderID, NDMID, MessageSchemaType.Xml, ApplicationCode.NDM, "", messageStream);

				adapter.Outbox.AddMessage(message);
				// Act
				adapter.SendMessages();

				// Assert
				var content = StreamExtensions.CompressAndEncode(messageStream).ReadToEnd();
				AssertInboxMessage(messagePK, LicencedSenderPK, ApplicationCode.NDM, NDMPK, "http://www.cargowise.com/Schemas/Universal/2011/11#UniversalInterchange", "", "", content, 0, 2);
				var memoryStream = new MemoryStream(Encoding.UTF8.GetBytes(messageStream.ReadToEnd().Trim()));
				var outboxContent = memoryStream.CompressAndEncode();
				Assert.IsTrue(FindOutboxMessage(messagePK, LicencedSenderPK, NDMPK, null, "", "", 0, memoryStream.ReadToEnd(), outboxContent.ReadToEnd()), "Outbox message not found");
				AssertInboxXmlContent(messagePK, null, memoryStream.ReadToEnd());
			}
		}

